const initial={sessions:[],expressions:[{id:'expr-conscious-time',expression:'Just conscious of time, ...',pattern:'Just conscious of [constraint], ...',category:'Meeting Facilitation',context:'Managing time diplomatically',example:'Just conscious of time, could we land on a decision?',whyUseful:'Signals a constraint without sounding abrupt.',dateLearned:'2026-08-11',sourceSessionId:'starter',status:'LEARNING'}],metadata:[{expressionId:'expr-conscious-time',practiceCount:0,successfulSpontaneousUses:0,contextsUsed:[],commonMistakes:[],lastPractisedAt:null,needsPractice:true,evidence:[]}],daily:{},weekly:{}};
function storageKey(){return authSession()?.user?.id?`${LEGACY_KEY}:${authSession().user.id}`:LEGACY_KEY}
function freshInitial(userId){const value=structuredClone(initial);if(userId){const starterId=`${userId}:expr-conscious-time`;value.expressions[0].id=starterId;value.metadata[0].expressionId=starterId}value.notes=[];return value}
let db=freshInitial(), mode='Meeting',level=2,pc,dc,stream,ticker,started,muted=false,aiResponding=false,transcript=[],state='ready',lastReview=null,currentScenario='',sessionConfigured=false,initialResponseRequested=false,partialUserTranscripts=new Map();
const scenarioTopics={
  Meeting:['Facilitate a requirements workshop where a senior stakeholder keeps jumping to solutions.','Lead a project meeting where two teams disagree about who owns an urgent dependency.','Bring a discussion back on track when the agenda is running fifteen minutes late.','Clarify next steps after a meeting where everyone has a different understanding.','Ask a quiet subject-matter expert for their view without putting them under pressure.','Challenge an optimistic delivery estimate while keeping the team constructive.','Summarise a complicated debate and guide the group towards a clear decision.','Handle a late executive request that was not included in the meeting agenda.'],
  Presentation:['Give a concise project update. Delivery is at risk and the full impact is still being confirmed.','Present a recommendation when the evidence supports two reasonable options.','Explain a technical change to non-technical leaders and ask for a decision.','Present early research findings while being transparent about important limitations.','Introduce a new process to colleagues who are likely to question its value.','Give a three-minute retrospective on what worked, what failed, and what changes next.','Present a revised timeline after an unexpected dependency caused a delay.','Pitch a small improvement that requires modest funding but saves staff time.'],
  'Small Talk':['Chat with a colleague before a Monday morning meeting after a wet weekend.','Talk with a colleague in the kitchen about their plans for the upcoming long weekend.','Welcome a new colleague and make natural conversation before a team lunch.','Chat before an online meeting about working from home and the morning commute.','Make conversation with a senior colleague while waiting for a workshop to begin.','Respond naturally when a colleague mentions they had a busy but enjoyable weekend.','Chat with someone from another team at a workplace social event.','Talk with a colleague about a local café, lunch options, and the afternoon workload.'],
  'Business English':['Clarify a vague requirement with an engineer without sounding bureaucratic.','Ask a stakeholder to confirm what success should look like before work begins.','Explain a concise follow-up after receiving conflicting instructions.','Tell a colleague their request needs more detail before you can estimate it.','Explain a trade-off between speed, scope, and quality in plain workplace English.','Check your understanding of a complex request without repeating every detail.','Ask for a realistic deadline when “as soon as possible” is used.','Explain why a proposed solution does not address the underlying business problem.'],
  'Challenge Me':['Push back when a senior sponsor asks to bring delivery forward by two weeks.','Respond when a stakeholder rejects your recommendation before hearing the evidence.','Tell a confident colleague their assumption is not supported by the available data.','Decline additional scope when your team has no capacity and offer an alternative.','Handle an interruption from a senior person who repeatedly talks over your update.','Explain that a promised date is no longer realistic without blaming another team.','Disagree diplomatically when a manager wants to skip an important validation step.','Respond to an ambiguous complaint and uncover the outcome the person needs.'],
};
const scenarios=Object.fromEntries(Object.entries(scenarioTopics).map(([category,topics])=>[category,topics[0]]));
function chooseScenario(category,{excludeCurrent=false}={}){const topics=scenarioTopics[category]||[],completed=new Set(db.sessions.filter(session=>session.mode===category).map(session=>session.scenario));let choices=topics.filter(topic=>!completed.has(topic)&&(!excludeCurrent||topic!==currentScenario));if(!choices.length)choices=topics.filter(topic=>!excludeCurrent||topic!==currentScenario);if(!choices.length)choices=topics;return choices[Math.floor(Math.random()*choices.length)]||scenarios[category]}
function ensureScenario(){if(!currentScenario)currentScenario=chooseScenario(mode)}
let cloudSaveTimer;
const save=()=>{localStorage.setItem(storageKey(),JSON.stringify(db));if(authSession()){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(()=>syncToCloud().then(syncPatternRecords).catch(showSyncError),350)}};

function showSyncError(error){console.error('Secure sync failed',error);document.querySelector('#syncStatus')?.replaceChildren(document.createTextNode('Sync paused'))}
async function syncPatternRecords(){const s=supabaseClient(),user=authSession()?.user;if(!s||!user)return;const occurrences={};for(const session of db.sessions){for(const weakness of session.recurringWeaknesses||[]){const key=weakness.trim().toLowerCase();if(!key)continue;occurrences[key]||={summary:weakness,evidence:[]};occurrences[key].evidence.push({sessionId:session.id,date:session.date,mode:session.mode})}}const rows=Object.entries(occurrences).filter(([,value])=>new Set(value.evidence.map(x=>x.sessionId)).size>=2).map(([key,value])=>({user_id:user.id,pattern_key:key,summary:value.summary,evidence:value.evidence,status:value.evidence.length>=3?'needs_attention':'stable',updated_at:new Date().toISOString()}));if(rows.length){const{error}=await s.from('user_patterns').upsert(rows,{onConflict:'user_id,pattern_key'});if(error)throw error}}
async function syncToCloud(){const s=supabaseClient(),user=authSession()?.user;if(!s||!user)return;const uid=user.id;
  const sessions=db.sessions.map(x=>({id:x.id,user_id:uid,occurred_at:x.date,mode:x.mode,difficulty:x.level,scenario:x.scenario||'',duration_seconds:x.durationSeconds||0,feedback:x.feedback,recurring_weaknesses:x.recurringWeaknesses||[]}));
  if(sessions.length){const{error}=await s.from('sessions').upsert(sessions);if(error)throw error}
  const turns=db.sessions.flatMap(x=>(x.transcript||[]).map(t=>({id:`${x.id}:${t.id}`,user_id:uid,session_id:x.id,speaker:t.speaker,content:t.text,occurred_at:t.at||x.date})));
  if(turns.length){const{error}=await s.from('transcript_turns').upsert(turns);if(error)throw error}
  const entries=db.expressions.map(x=>({id:x.id,user_id:uid,expression:x.expression,pattern:x.pattern,category:x.category,context:x.context,example:x.example,why_useful:x.whyUseful,date_learned:x.dateLearned||null,source_session_id:x.sourceSessionId,status:x.status||'NEW',archived:Boolean(x.archived),updated_at:new Date().toISOString()}));
  if(entries.length){const{error}=await s.from('playbook_entries').upsert(entries);if(error)throw error}
  const progress=db.metadata.map(x=>({user_id:uid,expression_id:x.expressionId,practice_count:x.practiceCount||0,successful_uses:x.successfulSpontaneousUses||0,contexts_used:x.contextsUsed||[],common_mistakes:x.commonMistakes||[],evidence:x.evidence||[],last_practised_at:x.lastPractisedAt,needs_practice:x.needsPractice!==false}));
  if(progress.length){const{error}=await s.from('playbook_progress').upsert(progress);if(error)throw error}
  const notes=(db.notes||[]).map(x=>({id:x.id,user_id:uid,source_session_id:x.sourceSessionId,category:x.mode||'Practice',original_version:x.myVersion||'',upgraded_version:x.upgradedVersion||'',note:x.note||'',created_at:x.createdAt,updated_at:x.updatedAt||x.createdAt}));
  if(notes.length){const{error}=await s.from('notes').upsert(notes);if(error)throw error}
  const daily=Object.values(db.daily||{}).map(x=>({user_id:uid,practice_date:x.date,content:x,updated_at:new Date().toISOString()}));
  if(daily.length){const{error}=await s.from('daily_progress').upsert(daily);if(error)throw error}
  const status=document.querySelector('#syncStatus');if(status)status.textContent='Saved securely'}

async function loadFromCloud(){const s=supabaseClient();const [sessionsResult,turnsResult,entriesResult,progressResult,notesResult,dailyResult]=await Promise.all([s.from('sessions').select('*').order('occurred_at'),s.from('transcript_turns').select('*').order('occurred_at'),s.from('playbook_entries').select('*'),s.from('playbook_progress').select('*'),s.from('notes').select('*'),s.from('daily_progress').select('*')]);for(const result of[sessionsResult,turnsResult,entriesResult,progressResult,notesResult,dailyResult])if(result.error)throw result.error;
  if(!sessionsResult.data.length&&!entriesResult.data.length&&!notesResult.data.length){db=freshInitial(authSession().user.id);localStorage.setItem(storageKey(),JSON.stringify(db));await syncToCloud();return}
  const turnsBySession=turnsResult.data.reduce((groups,turn)=>{(groups[turn.session_id]||=[]).push(turn);return groups},{});db.sessions=sessionsResult.data.map(x=>({id:x.id,date:x.occurred_at,mode:x.mode,level:x.difficulty,scenario:x.scenario,durationSeconds:x.duration_seconds,feedback:x.feedback,recurringWeaknesses:x.recurring_weaknesses||[],transcript:(turnsBySession[x.id]||[]).map(t=>({id:t.id.split(':').at(-1),speaker:t.speaker,text:t.content,at:t.occurred_at}))}));
  db.expressions=entriesResult.data.map(x=>({id:x.id,expression:x.expression,pattern:x.pattern,category:x.category,context:x.context,example:x.example,whyUseful:x.why_useful,dateLearned:x.date_learned,sourceSessionId:x.source_session_id,status:x.status,archived:x.archived}));
  db.metadata=progressResult.data.map(x=>({expressionId:x.expression_id,practiceCount:x.practice_count,successfulSpontaneousUses:x.successful_uses,contextsUsed:x.contexts_used,commonMistakes:x.common_mistakes,evidence:x.evidence,lastPractisedAt:x.last_practised_at,needsPractice:x.needs_practice}));
  db.notes=notesResult.data.map(x=>({id:x.id,createdAt:x.created_at,updatedAt:x.updated_at,sourceSessionId:x.source_session_id,mode:x.category,myVersion:x.original_version,upgradedVersion:x.upgraded_version,note:x.note}));db.daily=Object.fromEntries(dailyResult.data.map(x=>[x.practice_date,x.content]));localStorage.setItem(storageKey(),JSON.stringify(db))}

function renderSignIn(message=''){const publicSignup=authConfig()?.registrationMode==='public';el.innerHTML=`<main class="shell"><section class="intro auth-shell"><p class="eyebrow">AUSSIE WORKPLACE ENGLISH</p><h1>Welcome back.</h1><p class="sub">Sign in with your email and password. You only need email verification when creating an account or resetting a password.</p><div class="card auth-card"><label for="signInEmail">Email address</label><input id="signInEmail" type="email" autocomplete="email" placeholder="you@example.com"><label for="signInPassword">Password</label><input id="signInPassword" type="password" autocomplete="current-password" minlength="8" placeholder="At least 8 characters"><button class="primary" id="passwordSignIn">Sign in</button>${publicSignup?'<button class="ghost auth-secondary" id="createAccount">Create account</button>':''}<button class="text-button" id="forgotPassword" type="button">Forgot password?</button><div id="authMessage" class="sub" aria-live="polite">${escape(message)}</div></div></section></main>`;const email=()=>document.querySelector('#signInEmail').value.trim(),password=()=>document.querySelector('#signInPassword').value,messageBox=document.querySelector('#authMessage'),run=async(button,task)=>{button.disabled=true;messageBox.textContent='Please wait…';try{await task();location.reload()}catch(error){messageBox.textContent=error.message}finally{button.disabled=false}};document.querySelector('#passwordSignIn').onclick=event=>run(event.currentTarget,async()=>{if(!email()||!password())throw new Error('Enter your email and password.');await signInWithPassword(email(),password())});document.querySelector('#createAccount')?.addEventListener('click',event=>run(event.currentTarget,async()=>{if(!email()||password().length<8)throw new Error('Enter your email and a password of at least 8 characters.');const result=await signUpWithPassword(email(),password());if(!result.session){messageBox.textContent='Account created. Check your email once to verify it, then sign in with your password.';throw new Error(messageBox.textContent)}}));document.querySelector('#forgotPassword').onclick=async()=>{if(!email())return messageBox.textContent='Enter your email first.';try{await sendPasswordReset(email());messageBox.textContent='Password reset email sent. Open the newest link.'}catch(error){messageBox.textContent=error.message}}}
function renderPasswordReset(){el.innerHTML=`<main class="shell"><section class="intro auth-shell"><p class="eyebrow">ACCOUNT RECOVERY</p><h1>Choose a new password.</h1><div class="card auth-card"><label for="newPassword">New password</label><input id="newPassword" type="password" autocomplete="new-password" minlength="8"><button class="primary" id="savePassword">Save new password</button><div id="authMessage" class="sub" aria-live="polite"></div></div></section></main>`;document.querySelector('#savePassword').onclick=async event=>{const password=document.querySelector('#newPassword').value,message=document.querySelector('#authMessage');if(password.length<8)return message.textContent='Use at least 8 characters.';event.currentTarget.disabled=true;try{await updatePassword(password);message.textContent='Password updated. Opening your coach…';setTimeout(()=>location.replace('/'),500)}catch(error){message.textContent=error.message;event.currentTarget.disabled=false}}}
const wait=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
function renderSessionLoading(attempt=0){el.innerHTML=`<main class="shell"><section class="intro auth-shell"><p class="eyebrow">SECURE SIGN-IN</p><h1>${attempt?'Finishing your sign-in…':'Opening your workspace…'}</h1><p class="sub">${attempt?'Supabase is synchronising your new session. This can take a few seconds.':'Loading your private learning data.'}</p></section></main>`}
async function loadFromCloudWithRetry(){const delays=[0,2000,5000,10000,15000];for(let attempt=0;attempt<delays.length;attempt++){if(delays[attempt]){renderSessionLoading(attempt);await wait(delays[attempt])}try{return await loadFromCloud()}catch(error){const clockSkew=/jwt issued at future/i.test(error?.message||'');if(!clockSkew)throw error;if(attempt===delays.length-1)throw new Error('Your account is signed in, but Supabase is still synchronising the new session. Please wait one minute, then refresh this page.')}}}
async function boot(){try{const session=await initialiseAuth();if(session&&isPasswordRecovery())return renderPasswordReset();if(!session)return renderSignIn();renderSessionLoading();await verifyAccess();await loadFromCloudWithRetry();setup()}catch(error){renderSignIn(error.message)}}
function setup(){ensureScenario();el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span><div>Aussie Workplace<small>English Coach</small></div></div><nav class="nav"><button class="active">Practice</button><button id="history">History</button><button data-go="notes">My Notes</button></nav></header><section class="intro"><p class="eyebrow">VOICE-FIRST PRACTICE</p><h1>Speak your way into stronger workplace English.</h1><p class="sub">Have a realistic spoken conversation. Coaching stays out of the way until you finish.</p></section><section class="setup"><div class="card"><h2>Choose your practice</h2><div class="modes">${Object.keys(scenarios).map(x=>`<button class="mode ${x===mode?'active':''}" data-mode="${x}"><b>${x}</b><span>Realistic workplace role-play</span></button>`).join('')}</div><label>Difficulty</label><div>${[1,2,3].map(n=>`<button class="chip ${n===level?'active':''}" data-level="${n}">Level ${n}</button>`).join(' ')}</div><div class="topic-card"><div><span class="eyebrow">YOUR RANDOM TOPIC</span><p id="suggestedScenario">${escape(currentScenario)}</p></div><button id="nextScenario" class="ghost" type="button">Try another topic</button></div><label for="context">Or write your own scenario</label><input id="context" placeholder="e.g. scope discussion with a senior stakeholder"><button id="start" class="primary">Start voice session</button><div id="setupError"></div></div><aside class="card"><div class="privacy"><b>Voice privacy</b><p>Your microphone streams to OpenAI only during a session. This app saves the transcript and coaching review—not raw audio.</p></div><h3>Before you begin</h3><p class="sub">Use headphones if possible. Safari will ask for microphone access. Keep this screen open during practice.</p><p class="sub"><b>Typing is optional.</b> A fallback is available inside the voice session if microphone access fails.</p></aside></section></main>`;bindSetup()}
function bindSetup(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;currentScenario=chooseScenario(mode);setup()});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.level;setup()});document.querySelector('#nextScenario').onclick=()=>{currentScenario=chooseScenario(mode,{excludeCurrent:true});document.querySelector('#suggestedScenario').textContent=currentScenario;document.querySelector('#context').value=''};document.querySelector('#start').onclick=startVoice;document.querySelector('#history').onclick=renderHistory}
function context(){const input=document.querySelector('#context');if(input?.value.trim())currentScenario=input.value.trim();ensureScenario();return currentScenario}
function updateMicTransmission(){stream?.getAudioTracks().forEach(track=>{track.enabled=!muted&&!aiResponding})}
async function startVoice(){const btn=document.querySelector('#start'),err=document.querySelector('#setupError');btn.disabled=true;btn.textContent='Connecting securely…';transcript=[];partialUserTranscripts.clear();muted=false;aiResponding=false;state='ready';started=null;clearInterval(ticker);try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('This browser does not provide microphone access. Use Safari/Chrome over HTTPS.');audio.muted=false;audio.volume=1;stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});pc=new RTCPeerConnection();audio.srcObject=null;pc.ontrack=e=>{audio.srcObject=e.streams[0];audio.play().catch(()=>{})};stream.getTracks().forEach(t=>pc.addTrack(t,stream));dc=pc.createDataChannel('oai-events');dc.onmessage=onEvent;dc.onopen=()=>{state='listening';renderVoice();send({type:'response.create',response:{instructions:'Open the role-play now with one short, natural spoken turn.'}})};pc.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(pc.connectionState)){state='error';renderVoice('The voice connection was interrupted. You can end and keep the transcript.')}};const offer=await pc.createOffer();await pc.setLocalDescription(offer);const res=await fetch('/api/realtime/session',{method:'POST',headers:{'Content-Type':'application/sdp','X-Practice-Mode':encodeURIComponent(mode),'X-Difficulty':String(level),'X-Scenario':encodeURIComponent(context()),'X-Playbook':encodeURIComponent(playbookTargets())},body:offer.sdp});if(!res.ok)throw new Error((await res.text())||'Could not create the voice session.');await pc.setRemoteDescription({type:'answer',sdp:await res.text()});started=Date.now();renderVoice();ticker=setInterval(updateTimer,1000)}catch(e){stopMedia();btn.disabled=false;btn.textContent='Start voice session';err.innerHTML=`<div class="error"><b>Voice session could not start.</b><br>${escape(e.message)}<br><small>Check microphone permission, HTTPS, network access, and server configuration.</small></div>`}}
function playbookTargets(){if(mode!=='Playbook Review')return '';return db.expressions.filter(x=>['NEW','LEARNING'].includes(x.status)).slice(0,5).map(x=>`${x.expression} — ${x.context}`).join(' | ')}
function renderVoice(error=''){const secs=started?Math.floor((Date.now()-started)/1000):0;el.innerHTML=`<main class="practice"><div class="practice-inner"><p class="eyebrow">${mode.toUpperCase()} · LEVEL ${level}</p><h2>${context()}</h2><p class="scenario">Stay in the conversation. Coaching will appear only after you end.</p><div class="timer" id="timer">${fmt(secs)}</div><div class="orb ${state}"><div><div class="state">${state==='speaking'?'AI is speaking':state==='thinking'?'AI is thinking':state==='error'?'Connection issue':muted?'Microphone muted':'Listening'}</div><small>${muted?'Tap unmute to continue':aiResponding?'Microphone paused to prevent echo':'Speak when you’re ready'}</small></div></div><div class="statusline">${transcript.length?`${transcript.length} transcript turns captured`:'Preparing the conversation…'}</div>${error?`<div class="error">${escape(error)}</div>`:''}<div class="controls"><button class="round" id="mute">${muted?'Unmute':'Mute'}</button><button class="end" id="end">End session</button></div><details class="typing"><summary>Typing fallback</summary><textarea id="typed" rows="3" placeholder="Type a response only if voice is unavailable"></textarea><button class="round" id="sendText">Send</button></details></div></main>`;document.querySelector('#mute').onclick=toggleMute;document.querySelector('#end').onclick=endSession;document.querySelector('#sendText').onclick=sendTyped}
function onEvent(evt){let e;try{e=JSON.parse(evt.data)}catch{return}if(e.type==='session.updated'&&!sessionConfigured){sessionConfigured=true;if(!initialResponseRequested){initialResponseRequested=true;sendRaw({type:'response.create'})}}if(e.type==='input_audio_buffer.speech_started'&&!aiResponding){state='listening';renderVoice()}if(e.type==='input_audio_buffer.speech_stopped'&&!aiResponding){state='thinking';renderVoice()}if(e.type==='response.created'){aiResponding=true;updateMicTransmission();state='thinking';renderVoice()}if(e.type==='response.output_audio.delta'){aiResponding=true;updateMicTransmission();state='speaking';renderVoice()}if(e.type==='response.output_audio.done'||e.type==='response.done'){aiResponding=false;updateMicTransmission();state='listening';renderVoice()}if(e.type==='conversation.item.input_audio_transcription.delta'&&e.delta)partialUserTranscripts.set(e.item_id,(partialUserTranscripts.get(e.item_id)||'')+e.delta);if(e.type==='conversation.item.input_audio_transcription.completed'){const text=e.transcript||partialUserTranscripts.get(e.item_id);if(text)pushTurn('learner',text,e.item_id);partialUserTranscripts.delete(e.item_id)}if(e.type==='conversation.item.done'&&e.item){const text=extractItemText(e.item);if(text&&e.item.role==='user')pushTurn('learner',text,e.item.id);if(text&&e.item.role==='assistant')pushTurn('coach',text,e.item.id)}if(e.type==='response.output_audio_transcript.done'&&e.transcript)pushTurn('coach',e.transcript,e.item_id);if(e.type==='response.done')captureResponseItems(e.response);if(e.type==='error'){aiResponding=false;updateMicTransmission();state='error';renderVoice(e.error?.message||'The realtime service reported an error.')}}
function pushTurn(speaker,text,id){if(transcript.some(x=>x.id===id&&x.speaker===speaker))return;transcript.push({id:id||crypto.randomUUID(),speaker,text,at:new Date().toISOString()})}
function sendRaw(o){if(dc?.readyState==='open')dc.send(JSON.stringify(o))}
function send(o){if(!sessionConfigured&&o.type==='response.create'){sendRaw({type:'session.update',session:{type:'realtime',model:'gpt-realtime-2.1',instructions:roleplayInstructions(),output_modalities:['audio'],audio:{input:{transcription:{model:'gpt-4o-transcribe',language:'en'},turn_detection:{type:'semantic_vad',eagerness:'low',create_response:true,interrupt_response:true}},output:{voice:'marin'}}}});return}sendRaw(o)}
function roleplayInstructions(){return `You are already inside a ${mode} workplace role-play at Level ${level}. Scenario: ${context()}. Speak as a realistic Australian workplace participant, never as a general assistant or English teacher. Open with one scenario-specific line that requires the learner to respond. Keep turns brief, natural and professional. Let the learner speak most. Do not ask what they want to do and do not offer generic chat, planning or questions. Do not correct language during the role-play. ${mode==='Playbook Review'?`Create situations that invite these patterns without revealing them: ${playbookTargets()}`:''}`}
function extractItemText(item){return (item.content||[]).map(x=>x.transcript||x.text||'').filter(Boolean).join(' ').trim()}
function captureResponseItems(response){for(const item of response?.output||[]){const text=extractItemText(item);if(text)pushTurn('coach',text,item.id)}}
function toggleMute(){muted=!muted;updateMicTransmission();renderVoice()}
function sendTyped(){const t=document.querySelector('#typed').value.trim();if(!t)return;pushTurn('learner',t);send({type:'conversation.item.create',item:{type:'message',role:'user',content:[{type:'input_text',text:t}]}});send({type:'response.create'});document.querySelector('#typed').value=''}
async function endSession(){clearInterval(ticker);const duration=Math.max(0,Math.floor((Date.now()-started)/1000));stopMedia();el.innerHTML=`<main class="shell empty"><p class="eyebrow">COACH MODE</p><h1>Analysing your conversation…</h1><p class="sub">Building corrections, stronger Australian workplace phrasing and a whole-response upgrade.</p></main>`;const record={id:crypto.randomUUID(),date:new Date().toISOString(),mode,level,scenario:context(),durationSeconds:duration,transcript,feedback:null,expressionsPractised:[],recurringWeaknesses:[]};db.sessions.push(record);save();try{const res=await fetch('/api/analyse',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:record,playbook:db.expressions.slice(0,30)})});if(!res.ok)throw new Error(await res.text());record.feedback=await res.json();record.recurringWeaknesses=record.feedback.recurringWeaknesses||[];lastReview=record;integrate(record);save();renderReview(record)}catch(e){record.feedback={sessionSummary:'Your voice transcript was saved, but coaching analysis could not be generated.',whatISaid:transcript.filter(x=>x.speaker==='learner').map(x=>x.text),corrections:[],naturalVersions:[],upgradedResponses:[],deliveryFeedback:{available:false,reason:'No reliable audio-derived evidence was retained.'},keepThese:[],tryAgain:null};save();renderReview(record,e.message)}}
function integrate(r){const d=r.date.slice(0,10),f=r.feedback;for(const x of (f.keepThese||[]).slice(0,5)){let old=db.expressions.find(e=>e.expression.toLowerCase()===x.expression.toLowerCase());if(!old){old={...x,id:`expr-${crypto.randomUUID()}`,dateLearned:d,sourceSessionId:r.id,status:'NEW'};db.expressions.push(old);db.metadata.push({expressionId:old.id,practiceCount:0,successfulSpontaneousUses:0,contextsUsed:[],commonMistakes:[],lastPractisedAt:null,needsPractice:true,evidence:[]})}}db.daily[d]={date:d,sessionIds:[...(db.daily[d]?.sessionIds||[]),r.id],practised:[...new Set([...(db.daily[d]?.practised||[]),r.mode])],recurringIssues:[...new Set([...(db.daily[d]?.recurringIssues||[]),...(f.recurringWeaknesses||[])])],bestUpgrades:(f.upgradedResponses||[]).slice(0,3),newExpressions:(f.keepThese||[]).slice(0,5),tomorrowFocus:(f.tomorrowFocus||[]).slice(0,3)}}
function renderReview(r,err=''){const f=r.feedback;el.innerHTML=`<main class="shell review"><header class="top"><div class="brand"><span class="mark">AW</span>Session Review</div><button class="ghost" id="done">Done</button></header>${err?`<div class="error"><b>Analysis unavailable:</b> ${escape(err)}</div>`:''}<section><p class="eyebrow">${r.mode.toUpperCase()} · ${fmt(r.durationSeconds)}</p><h1>Your coaching review</h1></section>${section('Session summary',f.sessionSummary)}${listSection('What I said',f.whatISaid)}${listSection('Corrections',f.corrections)}${listSection('Natural Australian version',f.naturalVersions)}<section class="section"><h2>Upgraded Business English</h2>${(f.upgradedResponses||[]).map(x=>`<div class="compare"><div><b>MY VERSION</b><div class="quote">${escape(x.myVersion||'')}</div></div><div><b>UPGRADED VERSION</b><div class="quote up">${escape(x.upgradedVersion||'')}</div></div></div><p class="sub">${escape(x.whyBetter||'')}</p>`).join('')||'<p class="sub">No whole-response upgrade was needed.</p>'}</section>${section('Pronunciation / spoken delivery',f.deliveryFeedback?.available?f.deliveryFeedback.feedback:(f.deliveryFeedback?.reason||'No reliable audio-derived evidence was available. No pronunciation claims were made from transcript text alone.'))}<section class="section"><h2>Keep these</h2>${(f.keepThese||[]).slice(0,5).map(x=>`<div class="save-row"><div><b>${escape(x.expression)}</b><br><span class="sub">${escape(x.context||x.whyUseful||'')}</span></div><span class="tag">Saved</span></div>`).join('')||'<p class="sub">No new expression was strong enough to save.</p>'}</section>${f.tryAgain?`<section class="section"><h2>Try again by voice</h2><p>${escape(f.tryAgain)}</p><button class="primary" id="retry">Redo this moment</button></section>`:''}<section class="section transcript"><h2>Transcript</h2>${r.transcript.map(x=>`<details><summary><b>${x.speaker==='learner'?'You':'AI colleague'}</b></summary><p>${escape(x.text)}</p></details>`).join('')||'<p class="sub">No transcript turns were returned.</p>'}</section></main>`;document.querySelector('#done').onclick=setup;let b=document.querySelector('#retry');if(b)b.onclick=()=>{mode=r.mode;level=r.level;currentScenario=r.scenario;setup()}}
function section(h,c){return `<section class="section"><h2>${h}</h2><p>${escape(c||'No material issue identified.')}</p></section>`}function listSection(h,x=[]){return `<section class="section"><h2>${h}</h2>${x.length?`<ul>${x.map(v=>`<li>${escape(typeof v==='string'?v:JSON.stringify(v))}</li>`).join('')}</ul>`:'<p class="sub">No material issue identified.</p>'}</section>`}
function renderPlaybook(){const categories=[...new Set(db.expressions.map(x=>x.category).filter(Boolean))].sort();el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>My Aussie English Playbook</div><nav class="nav"><button data-go="practice">Practice</button><button class="active">Playbook</button><button data-go="history">History</button><button data-go="notes">My Notes</button></nav></header><section class="card"><div class="release-filters"><input id="playbookSearch" placeholder="Search expressions or contexts"><select id="playbookCategory"><option value="">All categories</option>${categories.map(x=>`<option>${escape(x)}</option>`).join('')}</select><select id="playbookStatus"><option value="">All statuses</option>${['NEW','LEARNING','ACTIVE','MASTERED'].map(x=>`<option>${x}</option>`).join('')}</select><select id="playbookSort"><option value="recent">Recently learned</option><option value="review">Needs review</option><option value="mastered">Mastered first</option></select></div></section><div class="card" id="playbookList" style="margin-top:16px"></div></main>`;bindPlaybookFilters()}
function bindPlaybookFilters(){const search=document.querySelector('#playbookSearch'),category=document.querySelector('#playbookCategory'),status=document.querySelector('#playbookStatus'),sort=document.querySelector('#playbookSort'),list=document.querySelector('#playbookList');function draw(){let items=db.expressions.filter(x=>(!category.value||x.category===category.value)&&(!status.value||x.status===status.value)&&(!search.value||JSON.stringify(x).toLowerCase().includes(search.value.toLowerCase())));if(sort.value==='recent')items.sort((a,b)=>(b.dateLearned||'').localeCompare(a.dateLearned||''));if(sort.value==='review')items.sort((a,b)=>Number((db.metadata.find(m=>m.expressionId===b.id)||{}).needsPractice)-Number((db.metadata.find(m=>m.expressionId===a.id)||{}).needsPractice));if(sort.value==='mastered')items.sort((a,b)=>Number(b.status==='MASTERED')-Number(a.status==='MASTERED'));list.innerHTML=items.map(x=>`<button class="record-row" data-expression-id="${x.id}"><span><b>${escape(x.expression)}</b><small>${escape(x.context)} · ${escape(x.category)}</small></span><span class="tag">${x.status}</span></button>`).join('')||'<p class="sub">No expressions match these filters.</p>';list.querySelectorAll('[data-expression-id]').forEach(button=>button.onclick=()=>renderExpression(button.dataset.expressionId))}search.oninput=draw;category.onchange=draw;status.onchange=draw;sort.onchange=draw;draw()}
function renderExpression(id){const x=db.expressions.find(item=>item.id===id),m=db.metadata.find(item=>item.expressionId===id)||{};if(!x)return renderPlaybook();el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>Playbook expression</div><button class="ghost" id="back">Back to Playbook</button></header><section class="section"><p class="eyebrow">${escape(x.category)} · ${escape(x.status)}</p><h1 style="font:42px Georgia,serif">${escape(x.expression)}</h1><h3>Reusable pattern</h3><p>${escape(x.pattern||'Not recorded')}</p><h3>Workplace context</h3><p>${escape(x.context||'Not recorded')}</p><h3>Example</h3><div class="quote up">${escape(x.example||'Not recorded')}</div><h3>Why it is useful</h3><p>${escape(x.whyUseful||'Not recorded')}</p></section><section class="section"><h2>Learning evidence</h2><p><b>Practised:</b> ${m.practiceCount||0} times</p><p><b>Successful spontaneous uses:</b> ${m.successfulSpontaneousUses||0}</p><p><b>Last practised:</b> ${m.lastPractisedAt?new Date(m.lastPractisedAt).toLocaleString():'Not yet'}</p><p><b>Common mistakes:</b> ${(m.commonMistakes||[]).map(escape).join(', ')||'None recorded'}</p></section></main>`;document.querySelector('#back').onclick=renderPlaybook}
function renderHistory(){const weekAgo=Date.now()-7*86400000,week=db.sessions.filter(x=>new Date(x.date).getTime()>=weekAgo),minutes=Math.round(week.reduce((n,x)=>n+(x.durationSeconds||0),0)/60),modes=Object.entries(week.reduce((a,x)=>(a[x.mode]=(a[x.mode]||0)+1,a),{}));el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>Practice history</div><nav class="nav"><button data-go="practice">Practice</button><button class="active">History</button><button data-go="notes">My Notes</button></nav></header><section class="card"><p class="eyebrow">THIS WEEK</p><div class="history-summary"><b>${week.length} sessions</b><b>${minutes} minutes speaking</b>${modes.map(([name,count])=>`<span>${escape(name)} × ${count}</span>`).join('')}</div></section><section class="card" style="margin-top:16px"><div class="release-filters"><input id="historySearch" placeholder="Search scenario or keyword"><select id="historyMode"><option value="">All practice types</option>${Object.keys(scenarios).map(x=>`<option>${x}</option>`).join('')}</select><select id="historyLevel"><option value="">All levels</option>${[1,2,3].map(x=>`<option value="${x}">Level ${x}</option>`).join('')}</select><input id="historyFrom" type="date" aria-label="From date"><input id="historyTo" type="date" aria-label="To date"></div></section><div class="card" id="historyList" style="margin-top:16px"></div><button class="ghost" id="historyMore" style="margin-top:14px">Load more</button></main>`;bindHistoryFilters()}
function bindHistoryFilters(){let limit=10;const search=document.querySelector('#historySearch'),modeFilter=document.querySelector('#historyMode'),levelFilter=document.querySelector('#historyLevel'),from=document.querySelector('#historyFrom'),to=document.querySelector('#historyTo'),list=document.querySelector('#historyList'),more=document.querySelector('#historyMore');function draw(){const items=db.sessions.slice().reverse().filter(x=>{const date=x.date.slice(0,10),hay=`${x.scenario} ${x.mode} ${(x.recurringWeaknesses||[]).join(' ')}`.toLowerCase();return(!search.value||hay.includes(search.value.toLowerCase()))&&(!modeFilter.value||x.mode===modeFilter.value)&&(!levelFilter.value||String(x.level)===levelFilter.value)&&(!from.value||date>=from.value)&&(!to.value||date<=to.value)});list.innerHTML=items.slice(0,limit).map(x=>`<div class="record-row"><button class="record-open" data-session-id="${x.id}"><span><b>${x.mode} · Level ${x.level}</b><small>${new Date(x.date).toLocaleString()} · ${fmt(x.durationSeconds||0)} · ${escape(x.scenario||'')}</small></span><span class="tag">${x.transcript.length} turns</span></button><button class="delete-action delete-session" data-delete-session="${x.id}" type="button">Delete</button></div>`).join('')||'<p class="sub">No sessions match these filters.</p>';more.hidden=items.length<=limit;list.querySelectorAll('[data-session-id]').forEach(button=>button.onclick=()=>renderSessionRecord(button.dataset.sessionId));list.querySelectorAll('[data-delete-session]').forEach(button=>button.onclick=async()=>{if(!confirm('Delete this practice session and its transcript permanently?'))return;const id=button.dataset.deleteSession,{error}=await supabaseClient().from('sessions').delete().eq('id',id);if(error)return alert(`Could not delete: ${error.message}`);db.sessions=db.sessions.filter(session=>session.id!==id);db.notes=db.notes.filter(note=>note.sourceSessionId!==id);save();renderHistory()})}for(const control of[search,modeFilter,levelFilter,from,to]){control.oninput=()=>{limit=10;draw()}}more.onclick=()=>{limit+=10;draw()};draw()}
function renderSessionRecord(id){const session=db.sessions.find(item=>item.id===id);if(!session)return renderHistory();if(session.feedback)return renderReview(session);el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>Saved session</div><button class="ghost" id="back">Back to History</button></header><section class="section"><p class="eyebrow">${escape(session.mode)} · LEVEL ${session.level}</p><h1>${escape(session.scenario)}</h1><p>${new Date(session.date).toLocaleString()} · ${fmt(session.durationSeconds||0)}</p></section><section class="section transcript"><h2>Transcript</h2>${session.transcript.map(turn=>`<details open><summary><b>${turn.speaker==='learner'?'You':'AI colleague'}</b></summary><p>${escape(turn.text)}</p></details>`).join('')||'<p class="sub">No transcript was captured.</p>'}</section></main>`;document.querySelector('#back').onclick=renderHistory}
function stopMedia(){stream?.getTracks().forEach(t=>t.stop());pc?.close();pc=null;dc=null;stream=null;audio.srcObject=null;aiResponding=false;sessionConfigured=false;initialResponseRequested=false;partialUserTranscripts.clear()}function updateTimer(){let t=document.querySelector('#timer');if(t)t.textContent=fmt(Math.floor((Date.now()-started)/1000))}function fmt(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}function escape(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function renderNotes(){const categories=['Meeting','Presentation','Small Talk','Business English','Challenge Me'];el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>My Notes</div><nav class="nav"><button data-go="practice">Practice</button><button data-go="history">History</button><button class="active">My Notes</button></nav></header><section class="intro"><p class="eyebrow">PERSONAL KNOWLEDGE BASE</p><h1>Ideas worth making your own.</h1><p class="sub">Notes inherit the practice category automatically. Filter by category and an inclusive date range, or reclassify an individual note.</p></section><section class="card" style="margin-top:24px"><div style="display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:12px;align-items:end"><div><label style="margin-top:0">Category</label><select id="noteCategoryFilter"><option value="">All categories</option>${categories.map(category=>`<option value="${category}">${category}</option>`).join('')}</select></div><div><label style="margin-top:0">From</label><input id="noteDateFrom" type="date"></div><div><label style="margin-top:0">To</label><input id="noteDateTo" type="date"></div><button class="ghost" id="clearNoteFilters">Clear filters</button></div><p class="sub" id="noteResultCount" style="margin-bottom:0"></p></section><div class="review" id="noteList" style="margin-top:18px">${noteCards(db.notes.slice().reverse(),categories)}</div></main>`;bindNoteControls(categories)}
function noteCards(notes,categories){return notes.map(note=>`<article class="section note-card" data-note-category="${escape(note.mode||'Practice')}" data-note-date="${note.createdAt.slice(0,10)}"><p class="eyebrow">${escape(note.mode||'PRACTICE')} · ${new Date(note.createdAt).toLocaleDateString()}</p><label>Category</label><select data-note-category-edit="${note.id}" disabled>${categories.map(category=>`<option value="${category}" ${category===(note.mode||'Practice')?'selected':''}>${category}</option>`).join('')}</select><h3>My original version</h3><div class="quote">${escape(note.myVersion)}</div><h3>Stronger version</h3><div class="quote up">${escape(note.upgradedVersion)}</div><label>My note</label><textarea data-note-text="${note.id}" rows="3" placeholder="Why is this useful? When will I use it?" readonly>${escape(note.note||'')}</textarea><div class="note-actions"><button class="note-action note-action-edit edit-saved-note" type="button" data-note-id="${note.id}">Edit note</button><button class="note-action note-action-save save-saved-note" type="button" data-note-id="${note.id}" disabled>Save changes</button><button class="delete-action delete-saved-note" type="button" data-note-id="${note.id}">Delete</button><span class="sub note-save-status" aria-live="polite"></span></div></article>`).join('')||'<div class="empty card"><h2>No notes saved yet</h2><p class="sub">Open a practice review and select Save to My Notes beneath an upgraded response.</p></div>'}
function bindNoteControls(categories){const category=document.querySelector('#noteCategoryFilter'),from=document.querySelector('#noteDateFrom'),to=document.querySelector('#noteDateTo'),count=document.querySelector('#noteResultCount');function filter(){let visible=0;document.querySelectorAll('.note-card').forEach(card=>{const noteDate=card.dataset.noteDate;const show=(!category.value||card.dataset.noteCategory===category.value)&&(!from.value||noteDate>=from.value)&&(!to.value||noteDate<=to.value);card.hidden=!show;if(show)visible++});count.textContent=`${visible} note${visible===1?'':'s'} shown${from.value||to.value?` · ${from.value||'earliest'} to ${to.value||'latest'}`:''}`}category.onchange=filter;from.onchange=filter;to.onchange=filter;document.querySelector('#clearNoteFilters').onclick=()=>{category.value='';from.value='';to.value='';filter()};document.querySelectorAll('.edit-saved-note').forEach(button=>button.onclick=()=>{const card=button.closest('.note-card'),text=card.querySelector('[data-note-text]'),select=card.querySelector('[data-note-category-edit]'),saveButton=card.querySelector('.save-saved-note');text.readOnly=false;select.disabled=false;saveButton.disabled=false;text.focus();button.textContent='Editing';button.classList.add('is-editing');card.querySelector('.note-save-status').textContent=''});document.querySelectorAll('.save-saved-note').forEach(button=>button.onclick=()=>{const card=button.closest('.note-card'),text=card.querySelector('[data-note-text]'),select=card.querySelector('[data-note-category-edit]'),note=db.notes.find(item=>item.id===button.dataset.noteId);if(!note)return;note.note=text.value.trim();note.mode=select.value;note.updatedAt=new Date().toISOString();card.dataset.noteCategory=select.value;save();text.readOnly=true;select.disabled=true;button.disabled=true;const editButton=card.querySelector('.edit-saved-note');editButton.textContent='Edit note';editButton.classList.remove('is-editing');card.querySelector('.note-save-status').textContent='Saved';filter()});document.querySelectorAll('.delete-saved-note').forEach(button=>button.onclick=async()=>{if(!confirm('Delete this note permanently?'))return;const id=button.dataset.noteId,{error}=await supabaseClient().from('notes').delete().eq('id',id);if(error)return alert(`Could not delete: ${error.message}`);db.notes=db.notes.filter(note=>note.id!==id);localStorage.setItem(storageKey(),JSON.stringify(db));renderNotes()});filter()}
const toolkit=[
['Asking / Clarifying','Just to clarify, are we saying that…?','Neutral and collaborative; useful before restating a decision.'],['Asking / Clarifying','Can I just check my understanding?','A natural way to verify detail without sounding challenging.'],['Asking / Clarifying','What would that look like in practice?','Moves an abstract proposal towards concrete behaviour.'],['Pushback','I’m not sure we can commit to that just yet.','Soft but clear; suitable when evidence is incomplete.'],['Pushback','We can look at bringing it forward, but there’d need to be a trade-off on scope.','Constructive pushback that offers a path forward.'],['Pushback','I’m not convinced that’s achievable with the current capacity.','Firm and direct; use when clarity matters.'],['Chasing / Following Up','Just checking whether you’ve had a chance to look at this.','Friendly for Teams or a routine follow-up.'],['Chasing / Following Up','Do you have a sense of when we might have the update?','Asks for timing without sounding accusatory.'],['Chasing / Following Up','Just conscious we’re waiting on this before we can move forward.','Explains the impact and increases urgency.'],['Meetings','Could I pause you there for a moment?','A polite spoken interruption.'],['Meetings','Just conscious of time, could we land on a decision?','Redirects discussion towards an outcome.'],['Meetings','Before we wrap up, can I confirm the actions?','Creates a clear close.'],['Stakeholder Management','We’re still confirming the full impact, so I’d avoid locking in a date just yet.','Communicates uncertainty while managing expectations.'],['Stakeholder Management','My recommendation is that we…','Signals the decision you want stakeholders to consider.'],['Presentation','The key point I’d like to leave you with is…','Useful emphasis before a conclusion.'],['Presentation','I don’t have that detail to hand, but I can confirm it after the session.','Professional way to handle an unknown.'],['Small Talk','Sounds like a good weekend.','Warm reaction without turning the exchange into an interview.'],['Small Talk','Yeah, I know the feeling.','Natural reciprocal reaction; follow with a small personal detail.']];
function renderToolkit(){el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>Workplace Toolkit</div><nav class="nav"><button data-go="practice">Practice</button><button class="active">Toolkit</button></nav></header><section class="intro"><p class="eyebrow">CURATED AUSTRALIAN WORKPLACE ENGLISH</p><h1>Useful language, organised by purpose.</h1><p class="sub">Browse independently, then save only the expressions you genuinely want to activate.</p></section><section class="card"><input id="toolkitSearch" placeholder="Search by situation, expression or tone"></section><div class="toolkit-grid" id="toolkitList" style="margin-top:16px"></div></main>`;const search=document.querySelector('#toolkitSearch'),list=document.querySelector('#toolkitList');function draw(){const query=search.value.toLowerCase(),items=toolkit.filter(x=>x.join(' ').toLowerCase().includes(query));list.innerHTML=items.map((x,i)=>`<article class="toolkit-card"><p class="eyebrow">${escape(x[0])}</p><h3>${escape(x[1])}</h3><p class="sub">${escape(x[2])}</p><button class="ghost toolkit-save" data-toolkit="${toolkit.indexOf(x)}">Save to Playbook</button></article>`).join('');list.querySelectorAll('.toolkit-save').forEach(button=>button.onclick=()=>{const x=toolkit[+button.dataset.toolkit];if(!db.expressions.some(e=>e.expression===x[1])){const id=`expr-${crypto.randomUUID()}`;db.expressions.push({id,expression:x[1],pattern:x[1],category:x[0],context:x[2],example:x[1],whyUseful:x[2],dateLearned:new Date().toISOString().slice(0,10),sourceSessionId:'toolkit',status:'NEW'});db.metadata.push({expressionId:id,practiceCount:0,successfulSpontaneousUses:0,contextsUsed:[],commonMistakes:[],lastPractisedAt:null,needsPractice:true,evidence:[]});save()}button.textContent='Saved';button.disabled=true})}search.oninput=draw;draw()}
function renderSayBetter(){el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>How can I say this?</div><nav class="nav"><button data-go="practice">Practice</button><button class="active">Say it better</button></nav></header><section class="intro"><p class="eyebrow">QUICK LANGUAGE COACH</p><h1>Turn a rough thought into natural workplace English.</h1><p class="sub">Describe the situation or type what you would currently say.</p></section><section class="card"><textarea id="sayInput" rows="5" placeholder="e.g. I need to tell a stakeholder we can’t commit to the date yet."></textarea><div class="row"><select id="sayChannel" style="width:auto"><option>Spoken meeting</option><option>Teams message</option><option>Email</option></select><button class="primary" id="saySubmit" style="width:auto;margin:0">Give me options</button></div><div id="sayResult"></div></section></main>`;document.querySelector('#saySubmit').onclick=async()=>{const input=document.querySelector('#sayInput').value.trim(),result=document.querySelector('#sayResult');if(!input)return;result.innerHTML='<p class="sub">Finding the clearest options…</p>';try{const response=await fetch('/api/say-better',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input,channel:document.querySelector('#sayChannel').value})});if(!response.ok)throw new Error(await response.text());const output=await response.json();result.innerHTML=`<div class="review" style="margin-top:20px">${['bestDefault','softer','moreDirect','spokenExample'].map(key=>output[key]?`<article class="section"><p class="eyebrow">${key.replace(/([A-Z])/g,' $1')}</p><p class="prompt">${escape(output[key])}</p><button class="ghost quick-save" data-expression="${escape(output[key])}">Save to Playbook</button></article>`:'').join('')}<p class="sub">${escape(output.whyItWorks||'')}</p></div>`;result.querySelectorAll('.quick-save').forEach(button=>button.onclick=()=>saveQuickExpression(button))}catch(error){result.innerHTML=`<div class="error">${escape(error.message)}</div>`}}}
function saveQuickExpression(button){const expression=button.dataset.expression;if(!db.expressions.some(x=>x.expression===expression)){const id=`expr-${crypto.randomUUID()}`;db.expressions.push({id,expression,pattern:expression,category:'Quick Coach',context:'How can I say this?',example:expression,whyUseful:'Chosen for active workplace use.',dateLearned:new Date().toISOString().slice(0,10),sourceSessionId:'quick-coach',status:'NEW'});db.metadata.push({expressionId:id,practiceCount:0,successfulSpontaneousUses:0,contextsUsed:[],commonMistakes:[],lastPractisedAt:null,needsPractice:true,evidence:[]});save()}button.textContent='Saved';button.disabled=true}
function renderPatterns(){const occurrences={};for(const session of db.sessions){for(const weakness of session.recurringWeaknesses||[]){const key=weakness.toLowerCase();occurrences[key]||={name:weakness,sessions:[]};occurrences[key].sessions.push(session)}}const patterns=Object.values(occurrences).filter(x=>new Set(x.sessions.map(s=>s.id)).size>=2);el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>My Patterns</div><nav class="nav"><button data-go="practice">Practice</button><button class="active">My Patterns</button></nav></header><section class="intro"><p class="eyebrow">COACHING INTELLIGENCE</p><h1>Recurring patterns, not isolated mistakes.</h1><p class="sub">A pattern appears only after evidence across at least two sessions.</p></section><div class="review" style="margin-top:24px">${patterns.map(x=>`<article class="section"><p class="eyebrow">${x.sessions.length>=3?'NEEDS ATTENTION':'STABLE'} · ${x.sessions.length} SESSIONS</p><h2>${escape(x.name)}</h2><p><b>Recent examples:</b></p><ul>${x.sessions.slice(-3).map(s=>`<li>${escape(s.mode)} — ${escape(s.scenario)}</li>`).join('')}</ul><p><b>Suggested practice:</b> Use Coach chooses for me to practise this under realistic pressure.</p></article>`).join('')||'<div class="empty card"><h2>Not enough evidence yet</h2><p class="sub">Complete a few more sessions. One isolated correction will never be promoted into a pattern.</p></div>'}</div></main>`}
function renderDailyNotes(){const notes=Object.values(db.daily||{}).sort((a,b)=>b.date.localeCompare(a.date));el.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="mark">AW</span>Daily Learning Notes</div><nav class="nav"><button data-go="practice">Practice</button><button class="active">Daily Notes</button></nav></header><section class="intro"><p class="eyebrow">ONE SYNTHESIS PER PRACTICE DAY</p><h1>Your learning, distilled by date.</h1></section><div class="review" style="margin-top:24px">${notes.map(n=>`<article class="section"><p class="eyebrow">${escape(n.date)}</p><h2>What I practised</h2><p>${escape((n.practised||[]).join(', '))}</p><h3>Recurring issues</h3><p>${escape((n.recurringIssues||[]).join('; ')||'None repeated')}</p><h3>Tomorrow’s focus</h3><ul>${(n.tomorrowFocus||[]).map(x=>`<li>${escape(x)}</li>`).join('')}</ul></article>`).join('')||'<div class="empty card">Your first daily note will appear after practice.</div>'}</div></main>`}
function enhanceReviewNotes(){document.querySelectorAll('.nav').forEach(nav=>{for(const[name,go]of[['Say it better','say'],['My Patterns','patterns'],['Daily Notes','daily'],['My Notes','notes']]){if(![...nav.querySelectorAll('button')].some(button=>button.textContent.trim()===name)){const button=document.createElement('button');button.dataset.go=go;button.textContent=name;nav.appendChild(button)}}});const setupArea=document.querySelector('.setup');if(setupArea&&!document.querySelector('#dailyWorkout')){const weaknesses=db.sessions.slice(-5).flatMap(x=>x.recurringWeaknesses||[]),focus=weaknesses.at(-1)||'communicate the main point clearly and confidently';const workout=document.createElement('section');workout.id='dailyWorkout';workout.className='workout';workout.style.gridColumn='1/-1';workout.innerHTML=`<p class="eyebrow" style="color:#d8a58e">COACH CHOOSES FOR ME</p><h2>Today’s 10-minute workout</h2><p>Focus: ${escape(focus)}</p><p style="color:#c5d5d0">The coach tests spontaneous workplace communication.</p><button class="primary" id="startWorkout">Start today’s workout</button>`;setupArea.prepend(workout);workout.querySelector('#startWorkout').onclick=()=>{mode=weaknesses.length?'Challenge Me':'Meeting';level=2;currentScenario=`A focused 10-minute workplace scenario designed to practise: ${focus}.`;startVoice()}}document.querySelectorAll('.compare:not([data-note-ready])').forEach((card,index)=>{card.dataset.noteReady='true';const action=document.createElement('div');action.style.cssText='grid-column:1/-1;background:#f4f1ea;border-radius:10px;padding:14px;margin-bottom:14px';action.innerHTML=`<label style="margin-top:0">My note (optional)</label><textarea rows="2" placeholder="What do I want to remember about this upgrade?" readonly></textarea><div class="note-actions"><button class="note-action note-action-edit edit-draft-note" type="button">Edit note</button><button class="note-action note-action-save save-note" type="button" data-upgrade-index="${index}">Save to My Notes</button></div>`;card.appendChild(action)})}
function ensureCoreNavigation(){document.querySelectorAll('.nav').forEach(nav=>{for(const[name,go]of[['Practice','practice'],['History','history']]){if(![...nav.querySelectorAll('button')].some(button=>button.textContent.trim()===name)){const button=document.createElement('button');button.dataset.go=go;button.textContent=name;nav.prepend(button)}}})}
function ensureAccountControls(){const header=document.querySelector('.top');if(!header||document.querySelector('#accountControls')||!authSession())return;const account=document.createElement('div');account.id='accountControls';account.className='account-controls';account.innerHTML=`<span id="syncStatus">Signed in · ${escape(authSession().user.email||'')}</span><button class="ghost" id="signOutButton" type="button">Sign out</button>`;header.appendChild(account);account.querySelector('#signOutButton').onclick=signOut}
new MutationObserver(()=>{enhanceReviewNotes();ensureCoreNavigation();ensureAccountControls()}).observe(el,{childList:true,subtree:true});
document.addEventListener('click',event=>{const button=event.target.closest('[data-delete-session]');if(!button)return;const linkedNotes=db.notes.filter(item=>item.sourceSessionId===button.dataset.deleteSession);setTimeout(()=>{if(button.isConnected||!linkedNotes.length)return;db.notes.push(...linkedNotes.filter(saved=>!db.notes.some(note=>note.id===saved.id)));localStorage.setItem(storageKey(),JSON.stringify(db))},800)},true);
document.addEventListener('click',(event)=>{const button=event.target.closest('.nav button'),destination=button?.dataset.go,routes={toolkit:renderToolkit,say:renderSayBetter,patterns:renderPatterns,daily:renderDailyNotes};if(routes[destination]){event.stopImmediatePropagation();routes[destination]()}},true);
document.addEventListener('focusin',(event)=>{if(event.target.matches('.compare textarea[readonly]')){event.target.readOnly=false;const editButton=event.target.closest('.compare')?.querySelector('.edit-draft-note');if(editButton){editButton.textContent='Editing';editButton.classList.add('is-editing')}}});
document.addEventListener('click',(event)=>{const nav=event.target.closest('.nav button');if(nav){const destination=nav.dataset.go||nav.textContent.trim().toLowerCase().replace('my ','');if(destination==='practice')setup();if(destination==='playbook')renderPlaybook();if(destination==='history')renderHistory();if(destination==='notes')renderNotes();return}const editDraft=event.target.closest('.edit-draft-note');if(editDraft){const text=editDraft.closest('div[style*="grid-column"]').querySelector('textarea');text.readOnly=false;text.focus();editDraft.textContent='Editing';return}const button=event.target.closest('.save-note');if(button){const card=button.closest('.compare'),quotes=card.querySelectorAll('.quote'),noteText=card.querySelector('textarea').value.trim();db.notes.push({id:crypto.randomUUID(),createdAt:new Date().toISOString(),sourceSessionId:lastReview?.id||null,mode:lastReview?.mode||'Practice',myVersion:quotes[0]?.textContent.trim()||'',upgradedVersion:quotes[1]?.textContent.trim()||'',note:noteText});save();card.querySelector('textarea').readOnly=true;button.textContent='Saved to My Notes';button.disabled=true}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});boot();
